import type { BrandAvatarItemProps } from 'components/BrandAvatar/Components/BrandAvatarItem/interface';

import { buildRoundedCountryFlagUrl } from '../../../../utils/countryContributionChartData';
import type { BeerEvolutionBreakdownData } from '../../../types';

const POSITIVE_COLOR = '#49764B';
const NEGATIVE_COLOR = '#A20A0A';
const NEUTRAL_COLOR = '#141414';
const MISSING_COLOR = '#5C5C5C';

/** BFF contract fixture — `portfolio-health-beer-evolution-breakdown` (16 columns). */
const BEER_EVOLUTION_LABELS = [
  'LY',
  'CHI',
  'CAN',
  'ITA',
  'GBR',
  'USA',
  'VNM',
  'BRA',
  'NAM',
  'BOL',
  'PRY',
  'FRA',
  'AUS',
  'URY',
  'Others',
  "Q1 '26",
] as const;

const BEER_EVOLUTION_FLAG_CODES = [
  'ABI',
  'CHN',
  'CAN',
  'ITA',
  'GBR',
  'USA',
  'VNM',
  'BRA',
  'NAM',
  'BOL',
  'PRY',
  'FRA',
  'AUS',
  'URY',
  'BRA',
  'ABI',
] as const;

const LY_ANCHOR_PHI = 72.4;
const QUARTER_ANCHOR_PHI = 68.9;

/** Contribution deltas (pp) — chart motor signs match Q1 vs LY row. */
const COUNTRY_CONTRIBUTION_DELTAS_PP = [
  -2.1, -1.8, -1.5, -1.2, -1.0, -0.9, -0.8, -0.7, -0.5, 0.6, 0.8, 1.0, 1.2, 1.5,
] as const;

const ABSOLUTE_PHI_BY_COLUMN = [
  '72.4',
  '70.3',
  '70.6',
  '70.9',
  '71.2',
  '71.4',
  '71.5',
  '71.6',
  '71.7',
  '71.9',
  '72.5',
  '72.7',
  '73.7',
  '74.9',
  '76.4',
  '68.9',
] as const;

const SKU_MIX_BY_COLUMN = [
  '42.0',
  '8.5',
  '6.2',
  '5.1',
  '4.8',
  '12.4',
  '3.2',
  '18.6',
  '2.1',
  '1.4',
  '2.8',
  '6.1',
  '4.5',
  '1.8',
  '13.2',
  '42.0',
] as const;

const SKU_Q1_VS_LY_BY_COLUMN: Array<number | null> = [
  null,
  -0.5,
  -0.3,
  0.1,
  -0.2,
  0.4,
  null,
  0.6,
  -0.1,
  0.2,
  0.3,
  0.5,
  0.7,
  0.1,
  0.9,
  -0.8,
];

const Q1_VS_LY_TOTAL_PP = -3.5;

const buildBrandAvatars = (
  labels: readonly string[],
  flagCodes: readonly string[],
): BrandAvatarItemProps[] =>
  labels.map((label, index) => ({
    title: label,
    mainBrand: {
      src: buildRoundedCountryFlagUrl(flagCodes[index]),
      alt: `${label} flag`,
    },
  }));

const formatSignedPp = (value: number) =>
  value >= 0 ? `+${value.toFixed(1)}` : value.toFixed(1);

const buildSignedDeltaCell = (value: number) => ({
  value: formatSignedPp(value),
  measure: 'pp',
  color: value >= 0 ? POSITIVE_COLOR : NEGATIVE_COLOR,
  trend: value >= 0 ? ('positive' as const) : ('negative' as const),
});

const buildMissingCell = () => ({
  value: '-',
  measure: '',
  color: MISSING_COLOR,
});

export const portfolioHealthBeerEvolutionBreakdownMock: BeerEvolutionBreakdownData =
  {
    values: [
      LY_ANCHOR_PHI,
      ...COUNTRY_CONTRIBUTION_DELTAS_PP,
      QUARTER_ANCHOR_PHI,
    ],
    labels: [...BEER_EVOLUTION_LABELS],
    formattedData: [[...ABSOLUTE_PHI_BY_COLUMN]],
    images: {
      data: buildBrandAvatars(BEER_EVOLUTION_LABELS, BEER_EVOLUTION_FLAG_CODES),
    },
    comparisonLine: {
      data: [
        {
          title: 'PHI',
          data: ABSOLUTE_PHI_BY_COLUMN.map((value) => ({
            value,
            measure: '',
            color: NEUTRAL_COLOR,
          })),
        },
        {
          title: 'Q1 vs LY',
          data: [
            buildMissingCell(),
            ...COUNTRY_CONTRIBUTION_DELTAS_PP.map((delta) =>
              buildSignedDeltaCell(delta),
            ),
            {
              value: formatSignedPp(Q1_VS_LY_TOTAL_PP),
              measure: 'pp',
              color: NEGATIVE_COLOR,
              trend: 'negative' as const,
            },
          ],
        },
        {
          title: 'SKU Mix',
          data: SKU_MIX_BY_COLUMN.map((value) => ({
            value,
            measure: '%',
            color: NEUTRAL_COLOR,
          })),
        },
        {
          title: 'SKU Q1 vs SKU LY',
          data: SKU_Q1_VS_LY_BY_COLUMN.map((value) => {
            if (value === null) {
              return buildMissingCell();
            }

            return buildSignedDeltaCell(value);
          }),
        },
      ],
    },
  };
